/*
 * A267860  An infinite ternary 3-Fibonacci sequence (replace each 00 factor
 *          of the Fibonacci word with 020).
 * https://oeis.org/A267860
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the nth symbol of the fixed point of the morphism 0 →
 *            01, 1 → 02, 2 → ε. The sequence is generated by iteratively
 *            applying this morphism until the desired index is within the
 *            word
 * Range:     u8 n <= 9759, u16 n <= 9759, u32 n <= 9759, u64 n <= 9759,
 *            u128 n <= 9759, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

static seq_t *cache = NULL;   /* array holding the generated word         */
static idx_t cache_len = 0;   /* number of symbols already in cache       */

seq_t a(idx_t n)
{
    /* If the cache already contains the desired index, return it. */
    if (n < cache_len)
        return cache[n];

    /* Initialise the cache with the first symbol of the word. */
    if (cache_len == 0) {
        cache_len = 1;
        cache = (seq_t *)malloc(sizeof(seq_t));
        cache[0] = 0;
    }

    /* Expand the word until it is long enough. */
    while (cache_len <= n) {
        /* Count symbols whose morphism produces output (0 or 1). */
        idx_t cnt01 = 0;
        for (idx_t i = 0; i < cache_len; ++i)
            if (cache[i] <= 1) ++cnt01;

        idx_t new_len = 2 * cnt01;
        seq_t *next = (seq_t *)malloc((size_t)new_len * sizeof(seq_t));

        idx_t pos = 0;
        for (idx_t i = 0; i < cache_len; ++i) {
            seq_t c = cache[i];
            if (c == 0) {          /* 0 -> 01 */
                next[pos++] = 0;
                next[pos++] = 1;
            } else if (c == 1) {   /* 1 -> 02 */
                next[pos++] = 0;
                next[pos++] = 2;
            }                      /* 2 -> ε, nothing appended */
        }

        free(cache);
        cache = next;
        cache_len = new_len;
    }

    return cache[n];
}
